let y = 1;

In what order are letters logged?
console.log("A");
setTimeout(() => console.log("B"), 0);
Promise.resolve().then(() => console.log("C"));
console.log("D");

What is logged?
const a = { x: { y: 1 } };
const b = { ...a };
b.x.y = 2;
console.log(a.x.y);

What is logged?
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}

In non-strict mode, what is logged?
const o = Object.freeze({ a: { b: 1 } });
o.a.b = 2;
console.log(o.a.b);
